import{_ as i,o as a,c as n,au as l}from"./chunks/framework.ChGI_eLK.js";import"./chunks/theme.CfmGloal.js";const u=JSON.parse('{"title":"Seven Elements Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"developer/changelog.md","filePath":"developer/changelog.md","lastUpdated":1783355325000}'),t={name:"developer/changelog.md"};function s(r,e,o,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="Seven_Elements_Changelog" tabindex="-1">Seven Elements Changelog <a class="header-anchor" href="#Seven_Elements_Changelog" aria-label="Permalink to “Seven Elements Changelog”">​</a></h1><p>This page serves as the changelog for Seven Elements, to be mainly used by addon developers or for reference, as the formatting for the changelong on Modrinth is quite ambigious and sometimes, hard to follow considering the multiple versions uploaded.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>A version number: <code>x.y.z</code>, will be inclusive of its LTS version number: <code>x.y.z+1-LTS.v</code>, unless said LTS version number exists as a separate version number listed in this changelog.</p></div><h2 id="Version_1.1:_Attunement_Update" tabindex="-1">Version 1.1: Attunement Update <a class="header-anchor" href="#Version_1.1:_Attunement_Update" aria-label="Permalink to “Version 1.1: Attunement Update”">​</a></h2><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>With the introduction of the Elemental Mastery attribute, <code>SevenElements.getLevelMultiplier()</code> and <code>ElementalReaction.getLevelMultiplier()</code> are both deprecated. You will now need an instance of <code>ElementalReaction</code> to properly calculate reaction damage, done via <code>ElementalReaction#getReactionStrength()</code>.</p><p>For a more in-depth developer changelog to this version of Seven Elements, refer to <a href="./changelog/Version_1.1">this page</a>.</p></div><h3 id="Version_1.1.0" tabindex="-1">Version 1.1.0 <a class="header-anchor" href="#Version_1.1.0" aria-label="Permalink to “Version 1.1.0”">​</a></h3><div class="shift-box"><h4 id="Additions" tabindex="-1">Additions <a class="header-anchor" href="#Additions" aria-label="Permalink to “Additions”">​</a></h4><ul><li>Added elemental attunement.</li><li>Added new items. <ul><li><code>seven-elements:elemental_rune</code></li><li><code>seven-elements:elemental_attunement_smithing_template</code></li><li><code>seven-elements:pyro_attunement_smithing_template</code></li><li><code>seven-elements:hydro_attunement_smithing_template</code></li><li><code>seven-elements:anemo_attunement_smithing_template</code></li><li><code>seven-elements:electro_attunement_smithing_template</code></li><li><code>seven-elements:dendro_attunement_smithing_template</code></li><li><code>seven-elements:cryo_attunement_smithing_template</code></li><li><code>seven-elements:geo_attunement_smithing_template</code></li></ul></li><li>Added advancement criterions. <ul><li><code>seven-elements:reaction_triggered</code></li><li><code>seven-elements:perform_attunement</code></li></ul></li><li>Added new attributes. <ul><li><code>seven-elements:elemental_mastery</code></li><li><code>seven-elements:critical_rate</code></li><li><code>seven-elements:critical_damage</code></li><li><code>seven-elements:shield_strength</code></li></ul></li><li>Added new recipes and recipe advancements.</li><li>Added new advancements.</li><li>Added subtitles.</li><li>Added new game rule. <ul><li><code>pyroDoesFireEffects</code> / <code>seven-elements:pyro_does_fire_effects</code></li></ul></li><li>Added uninfusing to the Infusion Table. (<a href="https://github.com/xrickastley/SevenElements/issues/8" target="_blank" rel="noreferrer">#8</a>)</li></ul><h4 id="Fixes" tabindex="-1">Fixes <a class="header-anchor" href="#Fixes" aria-label="Permalink to “Fixes”">​</a></h4><ul><li>Fixed <code>electroFromLightning</code> gamerule implementation (<a href="https://github.com/xrickastley/SevenElements/issues/11" target="_blank" rel="noreferrer">#11</a>)</li><li>Fixed <code>pyroFromFire</code> gamerule implementation (<a href="https://github.com/xrickastley/SevenElements/issues/13" target="_blank" rel="noreferrer">#13</a>)</li><li>Fixed <code>seven-elements:elemental_infusion</code> advancement criterion.</li><li>Fixed not being able to hit entities that take 0 DMG.</li><li>Fixed Elemental DMG Bonus attributes applying.</li><li>Fixed invalid elements being able to be applied as attunements.</li><li>Fixed damage origin for Electro-Charged and Burning ticks.</li><li>Fixed Frozen Crystallize not giving the Cryo Crystallize Shield.</li><li>Fixed command errors and message formatting for <code>/element</code>.</li><li>Fixed modifying item name via Anvil for infused items.</li><li>Fixed elemental infusion screen background being too dark.</li><li>[<strong>~1.20</strong>] Fixed thrown Tridents not applying their elemental infusions on hit.</li><li>[<strong>≥1.21.5</strong>] Fixed element rendering.</li><li>[<strong>≥1.21.5</strong>] Fixed possible error when upgrading a world from previous Minecraft versions.</li></ul><h4 id="Changes" tabindex="-1">Changes <a class="header-anchor" href="#Changes" aria-label="Permalink to “Changes”">​</a></h4><ul><li>Enhanced various advancements.</li><li>Increased minimum and maximum values for Elemental DMG Bonus% and RES% attributes.</li><li>Changed DMG calculations for Elemental Reactions due to Elemental Mastery.</li><li>Enhanced elemental infusion screen.</li><li>Pyro-infused Projectiles can now apply Fire effects.</li><li>Frozen is now stricter with disabling actions.</li><li>Shot projectiles can use their infusion when possible.</li><li>Infused items now display a static glint of their element.</li></ul></div><h2 id="Version_1.0:_Release" tabindex="-1">Version 1.0: Release <a class="header-anchor" href="#Version_1.0:_Release" aria-label="Permalink to “Version 1.0: Release”">​</a></h2><h3 id="Version_1.0.6" tabindex="-1">Version 1.0.6 <a class="header-anchor" href="#Version_1.0.6" aria-label="Permalink to “Version 1.0.6”">​</a></h3><div class="shift-box"><h4 id="Additions-1" tabindex="-1">Additions <a class="header-anchor" href="#Additions-1" aria-label="Permalink to “Additions”">​</a></h4><ul><li>Added <code>/element infusion apply &lt;target&gt; random command</code>. (<a href="https://github.com/xrickastley/SevenElements/issues/10" target="_blank" rel="noreferrer">#10</a>)</li><li>Added a game rule for the Overloaded Elemental Reaction creating Fire. (<a href="https://github.com/xrickastley/SevenElements/issues/12" target="_blank" rel="noreferrer">#12</a>)</li><li>Added initial groundwork for the Attunement system. (coming in a future update...)</li><li>Added ZH-CN localization for all versions of Seven Elements.</li></ul><h4 id="Fixes-1" tabindex="-1">Fixes <a class="header-anchor" href="#Fixes-1" aria-label="Permalink to “Fixes”">​</a></h4><ul><li>Fixed Elemental DMG Bonus attributes applying.</li></ul><h4 id="Changes-1" tabindex="-1">Changes <a class="header-anchor" href="#Changes-1" aria-label="Permalink to “Changes”">​</a></h4><ul><li>[<strong>≥1.21</strong>] Breezes now deal Anemo DMG</li></ul></div><h3 id="Version_1.0.5" tabindex="-1">Version 1.0.5 <a class="header-anchor" href="#Version_1.0.5" aria-label="Permalink to “Version 1.0.5”">​</a></h3><div class="shift-box"><h4 id="Additions-2" tabindex="-1">Additions <a class="header-anchor" href="#Additions-2" aria-label="Permalink to “Additions”">​</a></h4><ul><li>[<strong>26.1+patch.1</strong>] Added ZH-CN localization.</li></ul><h4 id="Fixes-2" tabindex="-1">Fixes <a class="header-anchor" href="#Fixes-2" aria-label="Permalink to “Fixes”">​</a></h4><ul><li>Fixed Sprawling Shots visually disappearing client-side.</li><li>Fixed Sprawling Shots targetting Creative Mode players.</li><li>Fixed elements and ICDs persisting after death.</li><li>[<strong>~1.20</strong>] Fixed data pack folder names. (<a href="https://github.com/xrickastley/SevenElements/issues/6" target="_blank" rel="noreferrer">#6</a>)</li><li>[<strong>≥1.21.5</strong>] Fixed possible memory leaks caused by repeated/unclosed BufferAllocator instances.</li><li>[<strong>1.21.11+patch.1</strong>] Fixed crash upon attempting to pierce with a Spear without an elemental infusion.</li></ul><h4 id="Changes-2" tabindex="-1">Changes <a class="header-anchor" href="#Changes-2" aria-label="Permalink to “Changes”">​</a></h4><ul><li>Optimized Sprawling Shot homing trajectory when close to the target.</li><li>Rephrased death messages.</li><li>Changed <code>overloadedBlockDestruction</code> to have a default value of <code>false</code>.</li></ul></div><h3 id="Version_1.0.4" tabindex="-1">Version 1.0.4 <a class="header-anchor" href="#Version_1.0.4" aria-label="Permalink to “Version 1.0.4”">​</a></h3><div class="shift-box"><h4 id="Fixes-3" tabindex="-1">Fixes <a class="header-anchor" href="#Fixes-3" aria-label="Permalink to “Fixes”">​</a></h4><ul><li>Fixed crits possibly not being registered visually.</li><li>Fixed Swirl (Frozen) triggering abnormally.</li><li>Fixed command message errors and argument parsing.</li></ul><h4 id="Changes-3" tabindex="-1">Changes <a class="header-anchor" href="#Changes-3" aria-label="Permalink to “Changes”">​</a></h4><ul><li>Removed <code>.sevenelements</code> from the maven_group.</li></ul></div><h3 id="Version_1.0.3" tabindex="-1">Version 1.0.3 <a class="header-anchor" href="#Version_1.0.3" aria-label="Permalink to “Version 1.0.3”">​</a></h3><div class="shift-box"><h4 id="Fixes-4" tabindex="-1">Fixes <a class="header-anchor" href="#Fixes-4" aria-label="Permalink to “Fixes”">​</a></h4><ul><li>Fixed crash when spawning Ender Dragon in a non-end dimension. (<a href="https://github.com/xrickastley/SevenElements/issues/4" target="_blank" rel="noreferrer">#4</a>)</li><li>[<strong>≥1.21.5</strong>] Fixed Hydro applying abnormally in comparison to previous versions.</li><li>[<strong>≥1.21.9</strong>] Fixed element icons rendering through blocks.</li></ul></div><h3 id="Version_1.0.3-LTS.1" tabindex="-1">Version 1.0.3-LTS.1 <a class="header-anchor" href="#Version_1.0.3-LTS.1" aria-label="Permalink to “Version 1.0.3-LTS.1”">​</a></h3><div class="shift-box"><h4 id="Additions-3" tabindex="-1">Additions <a class="header-anchor" href="#Additions-3" aria-label="Permalink to “Additions”">​</a></h4><ul><li>Added compatibility with Spell Power and More RPG Classes. (<a href="https://github.com/xrickastley/SevenElements/issues/2" target="_blank" rel="noreferrer">#2</a>)</li><li>[<strong>1.20.1</strong>] Added Sinytra Connector compatibility. (<a href="https://github.com/xrickastley/SevenElements/issues/3" target="_blank" rel="noreferrer">#3</a>)</li></ul></div><h3 id="Version_1.0.2" tabindex="-1">Version 1.0.2 <a class="header-anchor" href="#Version_1.0.2" aria-label="Permalink to “Version 1.0.2”">​</a></h3><div class="shift-box"><h4 id="Fixes-5" tabindex="-1">Fixes <a class="header-anchor" href="#Fixes-5" aria-label="Permalink to “Fixes”">​</a></h4><ul><li>Fixed issue when trying to summon Crystallize Shards via the <code>/summon</code> command.</li><li>Fixed broken contact links in <code>fabric.mod.json</code>.</li></ul><h4 id="Additions-4" tabindex="-1">Additions <a class="header-anchor" href="#Additions-4" aria-label="Permalink to “Additions”">​</a></h4><ul><li>Added item tag translations.</li></ul></div><h3 id="Version_1.0.1" tabindex="-1">Version 1.0.1 <a class="header-anchor" href="#Version_1.0.1" aria-label="Permalink to “Version 1.0.1”">​</a></h3><div class="shift-box"><h4 id="Fixes-6" tabindex="-1">Fixes <a class="header-anchor" href="#Fixes-6" aria-label="Permalink to “Fixes”">​</a></h4><ul><li>Fixed entity context in <code>/element infuse</code> command.</li></ul></div>',22)])])}const b=i(t,[["render",s]]);export{u as __pageData,b as default};
